import { Amplify, API, Auth } from 'aws-amplify';
import config from './dev';

// Configurar Amplify con la configuración de dev
Amplify.configure(config);

// Imprimir la configuración de la API
console.log('Configuración de la API:', config.API);

// Configurar el interceptor para agregar el token automáticamente
API.configure({
    endpoints: [
        {
            name: 'api',
            endpoint: config.API.endpoints[0].endpoint,
            region: config.Auth.region,
            custom_header: async () => {
                try {
                    const session = await Auth.currentSession();
                    const token = session.getIdToken().getJwtToken();
                    return {
                        'Authorization': `Bearer ${token}`,
                        'Content-Type': 'application/json'
                    };
                } catch (error) {
                    console.error('Error getting token:', error);
                    return {
                        'Content-Type': 'application/json'
                    };
                }
            }
        }
    ]
});
